input.command:
cd /project && cat > fib.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N>\n", argv[0]);
        return 1;
    }

    int n = atoi(argv[1]);
    if (n <= 0) {
        return 0;
    }

    long long a = 0, b = 1;

    printf("%lld\n", a);
    if (n > 1) {
        printf("%lld\n", b);
    }

    for (int i = 2; i < n; i++) {
        long long next = a + b;
        printf("%lld\n", next);
        a = b;
        b = next;
    }

    return 0;
}
EOF
cat fib.c

